@extends('layout') @section('title','Categories') @section('content') @include('admin.nav')<h1>Categories</h1><div class="panel"><h2 id="form-title">Add category</h2><form method="post" action="{{ route('admin.categories.save') }}">@csrf<input type="hidden" name="id" id="category-id"><label>Name</label><input name="name" id="category-name" required maxlength="100"><label>Description</label><textarea name="description" id="category-description"></textarea><label>Sort order</label><input type="number" name="sort_order" id="category-sort" min="0" value="0"><p><label><input type="checkbox" name="is_active" id="category-active" checked> Active</label></p><button type="submit">Save category</button> <button type="button" onclick="location.reload()">Clear</button></form></div><div class="panel table-wrap"><table><thead><tr><th>Name</th><th>Products</th><th>Visible</th><th>Actions</th></tr></thead><tbody>@foreach($categories as $category)<tr><td>{{ $category->name }}</td><td>{{ $category->products_count }}</td><td>{{ $category->is_active?'Yes':'No' }}</td><td class="actions"><button type="button" onclick='editCategory(@json($category))'>Edit</button><form method="post" action="{{ route('admin.categories.delete',$category) }}" onsubmit="return confirm('Delete category?')">@csrf @method('DELETE')<button type="submit">Delete</button></form></td></tr>@endforeach</tbody></table></div><script>function editCategory(c){document.querySelector('#form-title').textContent='Edit category';document.querySelector('#category-id').value=c.id;document.querySelector('#category-name').value=c.name;document.querySelector('#category-description').value=c.description||'';document.querySelector('#category-sort').value=c.sort_order;document.querySelector('#category-active').checked=!!c.is_active;scrollTo(0,0)}</script>@endsection
